fn copyto<T: Copy>(dst: Vec<T>, src: Vec<T>, mask: Vec<bool>) -> Vec<T> {
    // All input Vecs have the same length as per problem statement.
    // We'll build a new Vec by iterating over indices and choosing elements accordingly.
    let len = dst.len();

    // Preallocate result vector for efficiency
    let mut result = Vec::with_capacity(len);

    for i in 0..len {
        if mask[i] {
            result.push(src[i]);
        } else {
            result.push(dst[i]);
        }
    }

    result
}